from datetime import datetime
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field


class LocationPointInput(BaseModel):
    """One GPS event generated by the employee frontend."""

    client_event_id: UUID
    latitude: float = Field(ge=-90, le=90)
    longitude: float = Field(ge=-180, le=180)
    accuracy_meters: float | None = Field(default=None, ge=0)
    speed_mps: float | None = Field(default=None, ge=0)
    battery_percentage: int | None = Field(default=None, ge=0, le=100)
    recorded_at: datetime


class LocationBatchRequest(BaseModel):
    """Offline-safe batch of location events."""

    device_id: UUID
    points: list[LocationPointInput] = Field(min_length=1, max_length=500)


class LocationBatchResponse(BaseModel):
    """Result of processing a location batch."""

    accepted_count: int
    duplicate_count: int
    latest_recorded_at: datetime


class LiveLocationResponse(BaseModel):
    """Latest employee location shown to administrators."""

    id: UUID
    employee_id: UUID
    employee_code: str
    employee_name: str
    device_id: UUID | None
    latitude: float
    longitude: float
    accuracy_meters: float | None
    speed_mps: float | None
    battery_percentage: int | None
    recorded_at: datetime
    updated_at: datetime


class LocationRosterResponse(BaseModel):
    employee_id: UUID
    employee_code: str
    employee_name: str
    is_field_employee: bool
    latitude: float | None = None
    longitude: float | None = None
    accuracy_meters: float | None = None
    speed_mps: float | None = None
    battery_percentage: int | None = None
    recorded_at: datetime | None = None
    updated_at: datetime | None = None


class OwnLatestLocationResponse(BaseModel):
    """Authenticated employee's latest known location."""

    model_config = ConfigDict(from_attributes=True)

    id: UUID
    employee_id: UUID
    device_id: UUID | None
    latitude: float
    longitude: float
    accuracy_meters: float | None
    speed_mps: float | None
    battery_percentage: int | None
    recorded_at: datetime
    updated_at: datetime


class LocationHistoryResponse(BaseModel):
    """One historical GPS record."""

    model_config = ConfigDict(from_attributes=True)

    id: UUID
    client_event_id: UUID
    employee_id: UUID
    device_id: UUID | None
    latitude: float
    longitude: float
    accuracy_meters: float | None
    speed_mps: float | None
    battery_percentage: int | None
    recorded_at: datetime
    created_at: datetime
